-- ---------- quotes ----------
-- Attributed quotes are from public-domain sources. Unattributed lines are original to SupQuotes.
INSERT OR IGNORE INTO quotes (text, author_id, topic_id) VALUES
  ('Knowing your status is strength. Kindness ends stigma.', NULL, (SELECT id FROM topics WHERE slug='world-aids-day')),
  ('Facts protect. Stigma harms. Choose facts.', NULL, (SELECT id FROM topics WHERE slug='world-aids-day')),
  ('Disability is not inability. Build a world with room for everyone.', NULL, (SELECT id FROM topics WHERE slug='disability-day')),
  ('All human beings are born free and equal in dignity and rights.', (SELECT id FROM authors WHERE slug='udhr'), (SELECT id FROM topics WHERE slug='human-rights-day')),
  ('Rights are not gifts. They belong to every person, everywhere.', NULL, (SELECT id FROM topics WHERE slug='human-rights-day')),
  ('Six dots opened a world of words.', NULL, (SELECT id FROM topics WHERE slug='braille-day')),
  ('Education is the key that opens every other door.', NULL, (SELECT id FROM topics WHERE slug='education-day')),
  ('Courage doesn''t always roar. Sometimes it''s showing up for treatment one more day.', NULL, (SELECT id FROM topics WHERE slug='world-cancer-day')),
  ('To every fighter, survivor and caregiver: you are not alone.', NULL, (SELECT id FROM topics WHERE slug='world-cancer-day')),
  ('Your mother tongue is the music your heart learned first.', NULL, (SELECT id FROM topics WHERE slug='mother-language-day')),
  ('A world without wild things would be a poorer world for all of us.', NULL, (SELECT id FROM topics WHERE slug='wildlife-day')),
  ('Life is like pi: it goes on and on, and it''s never boring if you look closely.', NULL, (SELECT id FROM topics WHERE slug='pi-day')),
  ('Happiness grows when you share it.', NULL, (SELECT id FROM topics WHERE slug='happiness-day')),
  ('Poetry is what happens when words learn to fly.', NULL, (SELECT id FROM topics WHERE slug='poetry-day')),
  ('When the well''s dry, we know the worth of water.', (SELECT id FROM authors WHERE slug='benjamin-franklin'), (SELECT id FROM topics WHERE slug='water-day')),
  ('Save water today so tomorrow isn''t thirsty.', NULL, (SELECT id FROM topics WHERE slug='water-day')),
  ('Different, not less. Understand, accept, include.', NULL, (SELECT id FROM topics WHERE slug='autism-day')),
  ('Health is the crown on the well person''s head that only the sick can see.', NULL, (SELECT id FROM topics WHERE slug='health-day')),
  ('A sibling is a friend that life gives you for free.', NULL, (SELECT id FROM topics WHERE slug='siblings-day')),
  ('A book is a door you can open anywhere.', NULL, (SELECT id FROM topics WHERE slug='book-day')),
  ('Dance is the hidden language of the soul.', NULL, (SELECT id FROM topics WHERE slug='dance-day')),
  ('A free press is how a free people keeps its eyes open.', NULL, (SELECT id FROM topics WHERE slug='press-freedom-day')),
  ('I attribute my success to this: I never gave or took any excuse.', (SELECT id FROM authors WHERE slug='florence-nightingale'), (SELECT id FROM topics WHERE slug='nurses-day')),
  ('Nurses don''t just treat illnesses. They hold hands, calm fears and give hope.', NULL, (SELECT id FROM topics WHERE slug='nurses-day')),
  ('Family is where life begins and love never ends.', NULL, (SELECT id FROM topics WHERE slug='family-day')),
  ('Every breath without smoke is a gift to your future self.', NULL, (SELECT id FROM topics WHERE slug='no-tobacco-day')),
  ('Parents give us roots to grow and wings to fly.', NULL, (SELECT id FROM topics WHERE slug='parents-day')),
  ('The ocean gives us every second breath. Let''s give something back.', NULL, (SELECT id FROM topics WHERE slug='oceans-day')),
  ('Give blood. It costs you an hour and gives someone a lifetime.', NULL, (SELECT id FROM topics WHERE slug='blood-donor-day')),
  ('Music says what words cannot.', NULL, (SELECT id FROM topics WHERE slug='music-day')),
  ('Doctors give us the most precious gift of all: more time with the people we love.', NULL, (SELECT id FROM topics WHERE slug='doctors-day')),
  ('A little chocolate a day keeps the bad mood away.', NULL, (SELECT id FROM topics WHERE slug='chocolate-day')),
  ('Sometimes a single emoji says what a whole paragraph can''t. 😊', NULL, (SELECT id FROM topics WHERE slug='emoji-day')),
  ('Save the tiger, save the forest, save ourselves.', NULL, (SELECT id FROM topics WHERE slug='tiger-day')),
  ('Young people are not the leaders of tomorrow. They are the changemakers of today.', NULL, (SELECT id FROM topics WHERE slug='youth-day')),
  ('A photograph is a moment that refused to leave.', NULL, (SELECT id FROM topics WHERE slug='photography-day')),
  ('Teach one person to read and you light a lamp for a whole family.', NULL, (SELECT id FROM topics WHERE slug='literacy-day')),
  ('Peace begins with a smile, a kind word and an open hand.', NULL, (SELECT id FROM topics WHERE slug='peace-day')),
  ('Travel is the only thing you buy that makes you richer.', NULL, (SELECT id FROM topics WHERE slug='tourism-day')),
  ('Take care of your heart. It never takes a day off for you.', NULL, (SELECT id FROM topics WHERE slug='heart-day')),
  ('Coffee: because good days start with a good cup.', NULL, (SELECT id FROM topics WHERE slug='coffee-day')),
  ('It''s okay to not be okay. Asking for help is a sign of strength.', NULL, (SELECT id FROM topics WHERE slug='mental-health-day')),
  ('Be gentle with your mind. It is carrying more than anyone can see.', NULL, (SELECT id FROM topics WHERE slug='mental-health-day')),
  ('Educate a girl and you change the future of a whole community.', NULL, (SELECT id FROM topics WHERE slug='girl-child-day')),
  ('Food is life. No plate should be empty in a world that grows enough.', NULL, (SELECT id FROM topics WHERE slug='food-day')),
  ('We are many nations, but one human family.', NULL, (SELECT id FROM topics WHERE slug='un-day')),
  ('No act of kindness, no matter how small, is ever wasted.', (SELECT id FROM authors WHERE slug='aesop'), (SELECT id FROM topics WHERE slug='kindness-day')),
  ('Strong men also cry, care and ask for help.', NULL, (SELECT id FROM topics WHERE slug='mens-day'));

